const $ = (selector) => document.querySelector(selector);
const navItems = [
  ['overview', 'Overview'], ['treasury', 'Treasury'], ['payments', 'Payments'], ['approvals', 'Approvals'], ['agents', 'Agent rails'], ['proofs', 'Disclosures'], ['activity', 'Activity'], ['settings', 'Settings'],
];
let view = location.hash.slice(1) || 'overview';
const button = (label, action = '', style = 'primary') => `<button class="button ${style}" data-action="${action}">${label}</button>`;
const heading = (eyebrow, title, text, actions = '') => `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${text}</p></div><div class="actions">${actions}</div></div>`;
const empty = (title, text, action, label) => `<section class="panel empty"><b>${title}</b><p>${text}</p>${action ? button(label, action) : ''}</section>`;

function overview() {
  return heading('WORKSPACE', 'Your treasury starts here.', 'Connect your NEAR wallet, then set the rules before value moves.', button('Connect NEAR', 'connect')) + `<div class="overview-grid"><section class="balance-panel"><span class="eyebrow">TREASURY STATUS</span><div class="balance-total">—</div><div class="balance-caption">No wallet connected</div><div class="balance-actions">${button('Connect a wallet', 'connect')}${button('Configure treasury', 'treasury', 'secondary')}</div></section><section class="panel panel-pad"><span class="panel-label">GET READY TO MOVE</span><div class="flow-step"><i>1</i><div><h3>Connect custody</h3><p>Link a NEAR account to create your treasury boundary.</p></div></div><div class="flow-step"><i>2</i><div><h3>Set approvals</h3><p>Define who can approve consequential actions.</p></div></div><div class="flow-step"><i>3</i><div><h3>Configure agents</h3><p>Choose budgets, counterparties, and disclosure permissions.</p></div></div></section></div><section class="panel"><div class="panel-header"><div><h3>Payment activity</h3><p>Requests and outcomes appear here.</p></div></div>${empty('No payments yet', 'Create your treasury configuration to begin.')}</section>`;
}
function treasury() { return heading('TREASURY', 'Create the control surface.', 'A treasury combines custody, approvals, policy, and reporting.', button('Create treasury', 'setup')) + `<div class="cards"><section class="panel request"><span class="panel-label">CUSTODY</span><h3>Wallet connection</h3><p class="muted">Connect a NEAR account to establish the owner boundary.</p>${button('Connect NEAR', 'connect')}</section><section class="panel request"><span class="panel-label">APPROVALS</span><h3>Approval policy</h3><p class="muted">Set required signers and the actions they control.</p>${button('Configure approvals', 'approvals')}</section><section class="panel request"><span class="panel-label">REPORTING</span><h3>Private records</h3><p class="muted">Keep payment history and audit exports within the treasury.</p>${button('Open activity', 'activity')}</section></div>`; }
function payments() { return heading('PAYMENTS', 'Move value with intent.', 'Build a payment, apply the rules, then send it through its approval path.', button('New payment', 'payment')) + empty('No payment requests', 'Your payment queue will show every request, its policy result, and settlement outcome.', 'payment', 'Create payment'); }
function approvals() { return heading('APPROVALS', 'Every important decision has a path.', 'Set thresholds and signers once. Scrim routes each request to the right approval group.') + `<div class="cards"><section class="panel request"><span class="panel-label">THRESHOLDS</span><h3>What requires review?</h3><p class="muted">Choose the amount, asset, counterparty, or rule that starts an approval.</p>${button('Set thresholds', 'setup')}</section><section class="panel request"><span class="panel-label">SIGNERS</span><h3>Who can approve?</h3><p class="muted">Invite treasury signers and assign their authority.</p>${button('Add signers', 'setup')}</section></div>`; }
function agents() { return heading('AGENT RAILS', 'Autonomy inside hard boundaries.', 'An agent can act only when every budget, counterparty, approval, and disclosure rule passes.', button('Create agent policy', 'setup')) + `<div class="policy-grid"><section class="panel panel-pad"><span class="panel-label">POLICY BUILDER</span><div class="flow-step"><i>01</i><div><h3>Set a spend limit</h3><p>Give each agent a per-action and cumulative budget.</p></div></div><div class="flow-step"><i>02</i><div><h3>Allow counterparties</h3><p>Constrain where an agent may send value.</p></div></div><div class="flow-step"><i>03</i><div><h3>Define escalation</h3><p>Route actions outside normal bounds to a human approval.</p></div></div></section>${empty('No agent policy yet', 'Create a policy before an agent can request a payment.', 'setup', 'Create policy')}</div>`; }
function proofs() { return heading('DISCLOSURES', 'Share a fact, not your history.', 'Generate a reader-bound statement with an explicit expiry.', button('New disclosure', 'setup')) + `<div class="cards"><section class="panel request"><span class="panel-label">FACT</span><h3>Choose what to prove</h3><p class="muted">Payment receipt, balance threshold, payroll total, or agent compliance.</p></section><section class="panel request"><span class="panel-label">CONTROL</span><h3>Bind the reader and expiry</h3><p class="muted">Every disclosure has one intended reader and a bounded verification window.</p></section></div>`; }
function activity() { return heading('ACTIVITY', 'A private record of decisions.', 'Review treasury actions and prepare exports for the people who need them.', button('Prepare export', 'setup')) + empty('No treasury activity', 'Payment requests, approvals, disclosures, and agent decisions will appear here.'); }
function settings() { return heading('SETTINGS', 'Configure your workspace.', 'Manage wallet connection, treasury preferences, and security controls.') + `<section class="panel panel-pad"><div class="export-row"><div><h3>NEAR connection</h3><p>Connect your wallet to begin.</p></div>${button('Connect NEAR', 'connect')}</div><div class="export-row"><div><h3>Private record store</h3><p>Secure storage is ready for your treasury records.</p></div><span class="status">Ready</span></div></section>`; }
const pages = { overview, treasury, payments, approvals, agents, proofs, activity, settings };
function render() { view = location.hash.slice(1) || 'overview'; if (!pages[view]) view = 'overview'; $('#crumb').textContent = navItems.find(([id]) => id === view)[1]; $('#nav').innerHTML = navItems.map(([id, name]) => `<a href="#${id}" class="${id === view ? 'active' : ''}"><span>${name}</span></a>`).join(''); $('#main').innerHTML = pages[view](); }
function openConnect() { $('#modal-title').textContent = 'Connect your NEAR wallet'; $('#modal-body').innerHTML = `<p class="muted">Wallet authentication is the first step in creating a treasury. Use Settings to check a NEAR account while the wallet connection is being enabled.</p>`; $('#modal-submit').hidden = true; $('#modal').showModal(); }
function openSetup() { $('#modal-title').textContent = 'Treasury setup'; $('#modal-body').innerHTML = `<p class="muted">Choose the treasury owners, approval policy, assets, and agent rails. This setup will become available after wallet authentication is complete.</p>`; $('#modal-submit').hidden = true; $('#modal').showModal(); }
document.addEventListener('click', (event) => { const action = event.target.closest('[data-action]')?.dataset.action; if (action === 'connect') openConnect(); else if (action === 'setup') openSetup(); else if (pages[action]) location.hash = action; if (event.target.closest('[data-close]')) $('#modal').close(); });
$('#modal-form').addEventListener('submit', (event) => event.preventDefault());
$('#menu').addEventListener('click', () => $('#sidebar').classList.toggle('open'));
window.addEventListener('hashchange', render); render();
